// Mapeia eventos do Asaas para status do Maestr.ia
const body = $input.item.json.body || $input.item.json;
const event = body.event;
const payment = body.payment;

if (!event || !payment) {
  return [{ json: { skip: true, reason: 'Evento ou pagamento ausente' } }];
}

const statusMap = {
  PAYMENT_RECEIVED:  'pago',
  PAYMENT_CONFIRMED: 'pago',
  PAYMENT_OVERDUE:   'atrasado',
  PAYMENT_DELETED:   'cancelado',
  PAYMENT_REFUNDED:  'reembolsado',
  PAYMENT_RESTORED:  'pendente',
};

const newStatus = statusMap[event];
if (!newStatus) {
  return [{ json: { skip: true, reason: `Evento não tratado: ${event}` } }];
}

// externalReference deve ser o payment_id do Maestr.ia
const paymentId = payment.externalReference;
if (!paymentId) {
  return [{ json: { skip: true, reason: 'externalReference ausente — não é cobrança do Maestr.ia' } }];
}

return [{ json: {
  payment_id: paymentId,
  asaas_id: payment.id,
  event,
  new_status: newStatus,
  paid_at: payment.paymentDate ? new Date(payment.paymentDate).toISOString() : null,
  value: payment.value,
  net_value: payment.netValue,
  invoice_url: payment.invoiceUrl,
  bank_slip_url: payment.bankSlipUrl,
} }];

// Monta payload de atualização para o Maestr.ia
const data = $input.item.json;

const update = {
  status: data.new_status,
};

// Só atualiza paid_at se foi recebido
if (data.paid_at) {
  update.paid_at = data.paid_at;
}

// Atualiza metadata com dados do Asaas
update.metadata = {
  asaas_id: data.asaas_id,
  invoice_url: data.invoice_url,
  bank_slip_url: data.bank_slip_url,
  net_value: data.net_value,
  last_asaas_event: data.event,
  updated_from_asaas_at: new Date().toISOString(),
};

return [{ json: { payment_id: data.payment_id, update, event: data.event } }];
